parameters.jsCode:
const actividad = $('IA2 - Generación refuerzo').first().json.output;
const evaluacion = $('IA3 - Evaluación refuerzo').first().json.output;

const rag =
  $('Unificar contexto RAG refuerzo').first().json.contexto_rag ?? '';

const erroresIntento =
  $('Registrar intento').first().json.body?.errores ?? '';

const retos = Array.isArray(actividad.retos)
  ? actividad.retos
  : [];

const erroresTrabajados = Array.isArray(actividad.errores_trabajados)
  ? actividad.errores_trabajados
  : [];

// Texto completo de la actividad que debe inspeccionar el guardrail
const textoActividad = [
  actividad.titulo ?? '',
  actividad.enunciado ?? '',
  actividad.objetivo ?? '',
  ...(actividad.conceptos_utilizados ?? []),
  actividad.contexto_personalizacion ?? '',
  actividad.personalizacion_aplicada?.interes_principal ?? '',
  actividad.personalizacion_aplicada?.tipo_integracion ?? '',
  actividad.personalizacion_aplicada?.escenario ?? '',
  actividad.personalizacion_aplicada?.papel_alumnado ?? '',
  actividad.personalizacion_aplicada?.progresion ?? '',
  ...(actividad.personalizacion_aplicada?.elementos_recurrentes ?? []),
  ...erroresTrabajados,
  ...retos.flatMap(reto => [
    reto.situacion ?? '',
    reto.pregunta ?? ''
  ]),
  actividad.cierre_narrativo ?? ''
].join(' ').toLowerCase();

const textoRag = String(rag).toLowerCase();

const textoErrores = Array.isArray(erroresIntento)
  ? erroresIntento.join(' ').toLowerCase()
  : typeof erroresIntento === 'object' && erroresIntento !== null
    ? JSON.stringify(erroresIntento).toLowerCase()
    : String(erroresIntento).toLowerCase();

const motivos = [];


// -----------------------------------------------------
// 1. RESULTADO DE LA EVALUACIÓN MEDIANTE IA
// -----------------------------------------------------

if (evaluacion.valida !== true) {
  motivos.push(
    'IA3 ha marcado la actividad de refuerzo como no válida.'
  );
}

if (evaluacion.contenido_rag !== true) {
  motivos.push(
    'IA3 indica que existe contenido no respaldado por el RAG.'
  );
}

if (evaluacion.error_reforzado !== true) {
  motivos.push(
    'La actividad no trabaja correctamente el error registrado o el objetivo de refuerzo.'
  );
}

if (evaluacion.objetivo_correcto !== true) {
  motivos.push(
    'La actividad no mantiene correctamente el objetivo de refuerzo.'
  );
}

if (evaluacion.personalizacion_correcta !== true) {
  motivos.push(
    'La personalización no corresponde correctamente con el perfil o no está suficientemente integrada.'
  );
}


// -----------------------------------------------------
// 2. VIOLACIONES DETECTADAS POR IA3
// -----------------------------------------------------

const violacionesRag = Array.isArray(evaluacion.violaciones_rag)
  ? evaluacion.violaciones_rag
  : [];

if (violacionesRag.length > 0) {
  motivos.push(
    `IA3 ha detectado violaciones RAG: ${violacionesRag.join(' | ')}`
  );
}


// -----------------------------------------------------
// 3. COHERENCIA DE LOS ERRORES TRABAJADOS
// -----------------------------------------------------

const hayErroresReales =
  Array.isArray(erroresIntento)
    ? erroresIntento.length > 0
    : typeof erroresIntento === 'object' && erroresIntento !== null
      ? Object.keys(erroresIntento).length > 0
      : String(erroresIntento).trim() !== '';

if (hayErroresReales && erroresTrabajados.length === 0) {
  motivos.push(
    'Existen errores reales registrados, pero la actividad no identifica ningún error trabajado.'
  );
}

if (!hayErroresReales && erroresTrabajados.length > 0) {
  motivos.push(
    'La actividad declara errores trabajados aunque el intento no contiene errores concretos registrados.'
  );
}


// -----------------------------------------------------
// 4. EJEMPLOS NUMÉRICOS DE range()
// -----------------------------------------------------

function extraerRangeNumericos(texto) {
  return [
    ...String(texto).matchAll(/range\s*\(\s*(\d+)\s*\)/gi)
  ].map(match => Number(match[1]));
}

const ejemplosPermitidos = new Set(
  extraerRangeNumericos(textoRag)
);

const ejemplosActividad = [
  ...new Set(extraerRangeNumericos(textoActividad))
];

const ejemplosNoPermitidos = ejemplosActividad.filter(
  numero => !ejemplosPermitidos.has(numero)
);

if (ejemplosNoPermitidos.length > 0) {
  motivos.push(
    `La actividad introduce ejemplos de range() no presentes explícitamente en el RAG: ${ejemplosNoPermitidos
      .map(numero => `range(${numero})`)
      .join(', ')}.`
  );
}


// -----------------------------------------------------
// 5. CANTIDADES INDIRECTAS ASOCIADAS A range()
// -----------------------------------------------------

for (const reto of retos) {
  const textoReto = [
    reto.situacion ?? '',
    reto.pregunta ?? ''
  ].join(' ').toLowerCase();

  if (/range\s*\(/i.test(textoReto)) {
    const cantidades = [
      ...textoReto.matchAll(
        /\b(\d+)\s+(vueltas|repeticiones|veces|iteraciones)\b/gi
      )
    ].map(match => Number(match[1]));

    const cantidadesNoPermitidas = [
      ...new Set(
        cantidades.filter(
          numero => !ejemplosPermitidos.has(numero)
        )
      )
    ];

    if (cantidadesNoPermitidas.length > 0) {
      motivos.push(
        `Un reto asocia range() con cantidades no respaldadas explícitamente por el RAG: ${cantidadesNoPermitidas.join(', ')}.`
      );
    }
  }
}


// -----------------------------------------------------
// 6. GENERALIZACIÓN A range(n)
// -----------------------------------------------------

if (
  textoActividad.includes('range(n)') &&
  !textoRag.includes('range(n)')
) {
  motivos.push(
    'La actividad generaliza el contenido a range(n), aunque esa regla no aparece en el RAG.'
  );
}


// -----------------------------------------------------
// 7. VARIANTES DE print()
// -----------------------------------------------------

function extraerArgumentosPrint(texto) {
  return [
    ...String(texto).matchAll(/print\s*\(\s*([^)]+?)\s*\)/gi)
  ].map(match =>
    match[1]
      .replace(/\s+/g, ' ')
      .trim()
      .toLowerCase()
  );
}

const printPermitidos = new Set(
  extraerArgumentosPrint(textoRag)
);

const printActividad = [
  ...new Set(extraerArgumentosPrint(textoActividad))
];

const printNoPermitidos = printActividad.filter(
  argumento => !printPermitidos.has(argumento)
);

if (printNoPermitidos.length > 0) {
  motivos.push(
    `La actividad introduce variantes de print() no presentes explícitamente en el RAG: ${printNoPermitidos
      .map(argumento => `print(${argumento})`)
      .join(', ')}.`
  );
}


// -----------------------------------------------------
// 8. EXPRESIONES ACADÉMICAS CONTROLADAS
// -----------------------------------------------------

const expresionesControladas = [
  'off-by-one',
  'límite superior',
  'valor superior',
  'errores comunes'
];

for (const expresion of expresionesControladas) {
  if (
    textoActividad.includes(expresion) &&
    !textoRag.includes(expresion) &&
    !textoErrores.includes(expresion)
  ) {
    motivos.push(
      `La actividad introduce "${expresion}", que no aparece en el RAG ni en los errores reales del intento.`
    );
  }
}


// -----------------------------------------------------
// 9. PUNTUACIÓN
// -----------------------------------------------------

const puntuacionTotal = retos.reduce(
  (total, reto) => total + Number(reto.puntuacion ?? 0),
  0
);

if (Number(actividad.puntuacion_maxima) !== 10) {
  motivos.push(
    'La puntuación máxima de la actividad debe ser exactamente 10.'
  );
}

if (puntuacionTotal !== 10) {
  motivos.push(
    `La suma de las puntuaciones de los retos debe ser 10 y actualmente es ${puntuacionTotal}.`
  );
}


// -----------------------------------------------------
// RESULTADO FINAL
// -----------------------------------------------------

const validaFinal = motivos.length === 0;

return {
  json: {
    actividad,
    evaluacion_ia: evaluacion,
    guardrail_determinista: {
      valido: validaFinal,
      motivos
    },
    valida_final: validaFinal
  }
};

const items = $input.all();

const documentos = items
  .map((item) => ({
    contenido: item.json.document?.pageContent ?? '',
    metadata: item.json.document?.metadata ?? {},
    score: item.json.score ?? null,
  }))
  .filter((doc) => doc.contenido);

const contextoRag = documentos
  .map(
    (doc, index) =>
      `FRAGMENTO ${index + 1}:\n${doc.contenido}`
  )
  .join('\n\n');

return [
  {
    json: {
      contexto_rag: contextoRag,
      referencias_rag: documentos.map((doc) => ({
        metadata: doc.metadata,
        score: doc.score,
      })),
    },
  },
];

